SourceCode.Declaration:
/// <summary>
/// temporary table AVAMarkupTransTmp
/// </summary>
public class AVAMarkupTransTmp extends common
{
}

Method.Source:
/// <summary>
/// initialize from MarkupTrans record
/// </summary>
/// <param name = "_markupTrans">MarkupTrans</param>
public void initFromMarkupTrans(MarkupTrans _markupTrans)
{
    this.CalcQty        = _markupTrans.AVACalcQty;
    this.CurrencyCode   = _markupTrans.CurrencyCode;
    this.MarkupCategory = _markupTrans.MarkupCategory;
    this.MarkupCode     = _markupTrans.MarkupCode;
    this.ModuleCategory = _markupTrans.ModuleCategory;
    this.ModuleType     = _markupTrans.ModuleType;
    this.Txt            = _markupTrans.Txt;
    this.Value          = _markupTrans.Value;
}

/// <summary>
/// set the field CalculatedAmount and its ratio to the original Amount 
/// </summary>
/// <param name = "_calculatedAmount">AmountCur</param>
/// <param name = "_lineAmount">Original Amount, calculation is based on</param>
public void setCalculatedAmount(AmountCur _calculatedAmount, AmountCur _lineAmount)
{
    this.CalculatedAmount   = _calculatedAmount;
    this.Percent            = _calculatedAmount/_lineAmount*100;
}

/// <summary>
/// initializes the Tmp records for the from AVAHKPurchPriceInfo based on a PriceDiscTable record and TransDate
/// </summary>
/// <param name = "_markupTransTmp">AVAMarkupTransTmp</param>
/// <param name = "_priceDiscTable">PriceDiscTable</param>
/// <param name = "_transDate">TransDate</param>
public static void createRecordsFromPriceDiscTable(AVAMarkupTransTmp   _markupTransTmp, PriceDiscTable _priceDiscTable, TransDate _transDate)
{
    Amount                  lineAmount;
    MarkupAutoLine          avaAutoLine;
    MarkupAutoTable         avaAutoTable;
    VendGroupId             locVendGroupId;
    ItemGroupId             locItemGroupId;
    MarkupTrans             locMarkupTrans;

    lineAmount = _priceDiscTable.avaCalcDiscountedAmount(_transDate);

    if(_priceDiscTable.AccountCode == PriceDiscPartyCodeType::GroupId)
    {
        locVendGroupId  = _priceDiscTable.AccountRelation;
    }
    else if(_priceDiscTable.AccountCode == PriceDiscPartyCodeType::Table)
    {
        locVendGroupId  = VendTable::find(_priceDiscTable.AccountRelation).VendGroup;
    }

    //if(_priceDiscTable.ItemCode == PriceDiscProductCodeType::GroupId)
    //{
    //    locItemGroupId  = _priceDiscTable.ItemRelation;
    //}
    if(_priceDiscTable.ItemCode == PriceDiscProductCodeType::Table)
    {
        locItemGroupId  = InventTable::find(_priceDiscTable.ItemRelation).inventTableModulePurch().MarkupGroupId;
    }

    delete_from _markupTransTmp;

    while select * from avaAutoLine
    join avaAutoTable
    where avaAutoLine.TableTableId == avaAutoTable.TableId
    && avaAutoLine.TableRecId == avaAutoTable.RecId
    && avaAutoTable.ModuleType == MarkupModuleType::Vend
    && (avaAutoTable.AccountCode == TableGroupAll::All
        || (avaAutoTable.AccountCode == TableGroupAll::GroupId
            && avaAutoTable.AccountRelation == locVendGroupId)
        || (avaAutoTable.AccountCode == TableGroupAll::Table
            && avaAutoTable.AccountRelation == _priceDiscTable.AccountRelation))
    && (avaAutoTable.ItemCode == TableGroupAll::All
        || (avaAutoTable.ItemCode == TableGroupAll::GroupId
            && avaAutoTable.ItemRelation == locItemGroupId)
        ||(avaAutoTable.ItemCode == TableGroupAll::Table
            && avaAutoTable.ItemRelation == _priceDiscTable.ItemRelation))
    {
        if((avaAutoTable.ModuleCategory == HeadingLine::Heading
                && (avaAutoLine.MarkupCategory != MarkupCategory::Percent
                || avaAutoLine.AVAFromDate > _transDate
                || (avaAutoLine.AVAToDate < _transDate
                    && avaAutoLine.AVAToDate != dateNull())))
            || (avaAutoTable.ModuleCategory == HeadingLine::Line
                && ((avaAutoLine.MarkupCategory != MarkupCategory::AVAMTZ
                        && avaAutoLine.MarkupCategory != MarkupCategory::Pcs
                        && avaAutoLine.MarkupCategory != MarkupCategory::Percent)
                    || avaAutoLine.AVAFromDate > _transDate
                    || (avaAutoLine.AVAToDate < _transDate
                        && avaAutoLine.AVAToDate != dateNull()))))
        {
            continue;
        }

        _markupTransTmp.clear();
        AVAChargeSpecification chargeSpecificationLoc = AVAChargeSpecification::find(avaAutoTable.AccountCode, avaAutoTable.AccountRelation, avaAutoTable.ItemCode, avaAutoTable.ItemRelation, AVAChargeType::MTZ, _transDate);

        locMarkupTrans.initFromMarkupAutoLine(avaAutoLine);
        _markupTransTmp.initFromMarkupTrans(locMarkupTrans);
        switch (locMarkupTrans.MarkupCategory)
        {
            case MarkupCategory::AVAMTZ : 
                if (!_PriceDiscTable.AVAEffectivePrice)
                {
                    PriceUnit      priceUnitPurch = UnitOfMeasureConverter::convert(chargeSpecificationLoc.PriceUnit,UnitOfMeasure::findBySymbol(chargeSpecificationLoc.CalculationUnit).RecId,UnitOfMeasure::findBySymbol(_priceDiscTable.UnitId).RecId,NoYes::No,InventTable::find(_priceDiscTable.AccountRelation).Product);
                    _markupTransTmp.Value = (priceUnitPurch != 0 ?  chargeSpecificationLoc.Charge / priceUnitPurch  : chargeSpecificationLoc.Charge) * _priceDiscTable.PriceUnit;
                    _markupTransTmp.CalcQty      = chargeSpecificationLoc.CalcQty;
                    _markupTransTmp.CurrencyCode = chargeSpecificationLoc.CurrencyCode;
                    if (lineAmount != 0)
                    {
                        _markupTransTmp.Percent       = (_markupTransTmp.Value  / (lineAmount))  * 100;
                    }
                }
                else
                {
                    _markupTransTmp.Value = 0;
                }
                break;
            case MarkupCategory::Pcs:
                InventTableModule          inventTableModulePurch = InventTable::find(_priceDiscTable.ItemRelation).inventTableModulePurch();
                PriceUnit   purchPriceUnit =  inventTableModulePurch.priceUnit();
                UnitOfMeasureSymbol      purchUnitId    = inventTableModulePurch.UnitId;
                PriceUnit   tradeArgmPriceUnit;

                if (_priceDiscTable.UnitId != purchUnitId)
                {
                    tradeArgmPriceUnit = UnitOfMeasureConverter::convert(purchPriceUnit,UnitOfMeasure::findBySymbol(purchUnitId).RecId,UnitOfMeasure::findBySymbol(_priceDiscTable.UnitId).RecId,NoYes::No,InventTable::find(_priceDiscTable.AccountRelation).Product);
                }
                else
                {
                    tradeArgmPriceUnit = purchPriceUnit;
                }

                _markupTransTmp.Value = (tradeArgmPriceUnit != 0 ? avaAutoLine.Value / tradeArgmPriceUnit : avaAutoLine.Value) * _priceDiscTable.priceUnit;
                if (lineAmount != 0)
                    {
                        _markupTransTmp.Percent = (_markupTransTmp.Value / (lineAmount))  * 100;
                    }
                break;
            case MarkupCategory::Percent:
                _markupTransTmp.Value = lineAmount * avaAutoLine.Value / 100;
                _markupTransTmp.Percent = avaAutoLine.Value;
                break;
        }   

       //_markupTransTmp.setCalculatedAmount(locMarkupTrans.calcDistributionAmount(_priceDiscTable.PriceUnit, lineAmount, _transDate), lineAmount);

        if(_markupTransTmp.Value != 0)
        {
            _markupTransTmp.insert();
        }
    }
}
